// Payload normalizado que manda Supabase (trigger lead.assigned o cron followup.overdue):
// { event, user:{id,email,phone,name}, preferred_channel, client:{...}, message }
const raw = $input.first().json.body ?? $input.first().json;
const user = raw.user ?? {};
const client = raw.client ?? {};
const channelMap = { sms: 'SMS', whatsapp: 'WhatsApp', email: 'Email' };
const ghlType = channelMap[String(raw.preferred_channel || 'email').toLowerCase()] || 'Email';
if (!user.id) throw new Error('Payload sin user.id');
if (!user.email && !user.phone) throw new Error('El vendedor no tiene email ni teléfono');
return [{
  json: {
    event: raw.event,
    ghlType,
    message: raw.message || 'Tenés una novedad en CRM Lite',
    user,
    client,
    // Para poder mensajear al vendedor por GHL necesitamos que exista como contacto.
    // Lo upserteamos como contacto INTERNO, tag crm-lite:internal-user para filtrarlo.
    sellerUpsert: {
      locationId: 'YF36RPtJ1lRQBqM7Qxgc',
      name: user.name || user.email || 'Vendedor',
      email: user.email || undefined,
      phone: user.phone || undefined,
      tags: ['crm-lite:internal-user']
    }
  }
}];

const res = $input.first().json;
const ghlContact = res.contact ?? res.data?.contact ?? res;
const contactId = ghlContact.id ?? ghlContact.contactId;
const src = $('Parse & Route').first().json;
if (!contactId) throw new Error('GHL upsert del vendedor no devolvió contactId');
// El cuerpo del mensaje depende del canal. VERIFICAR contra la doc de GHL Conversations
// API antes de activar (subject/html para Email; message para SMS/WhatsApp).
const body = src.ghlType === 'Email'
  ? { type: 'Email', contactId, subject: 'CRM Lite', html: `<p>${src.message}</p>` }
  : { type: src.ghlType, contactId, message: src.message };
return [{ json: { messageBody: body, user: src.user, client: src.client, event: src.event, channel: src.ghlType } }];

